ALTER TABLE public.learning_questions ADD COLUMN IF NOT EXISTS question_type text NOT NULL DEFAULT 'unclassified';
ALTER TABLE public.learning_questions ADD COLUMN IF NOT EXISTS classification_source text NOT NULL DEFAULT '';
ALTER TABLE public.learning_questions ADD COLUMN IF NOT EXISTS classification_reviewed_at timestamptz;
ALTER TABLE public.learning_lessons ADD COLUMN IF NOT EXISTS pathways text[] NOT NULL DEFAULT ARRAY['naturalisation','resident','sejour'];
ALTER TABLE public.learning_tests ADD COLUMN IF NOT EXISTS question_type text NOT NULL DEFAULT 'all';
UPDATE public.question_drafts SET payload=payload||jsonb_build_object('question_type','unclassified','classification_source','') WHERE NOT(payload ? 'question_type');
COMMENT ON COLUMN public.learning_lessons.pathways IS 'Existing common lessons remain shared; editors review pathway applicability before changing this field.';
CREATE OR REPLACE FUNCTION public.civic_topic(p_theme text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN p_theme IN ('Valeurs de la République','Principes et valeurs','Principes et valeurs de la République française') THEN 'Principes et valeurs de la République française' WHEN p_theme IN ('Institutions','Institutions françaises','Système institutionnel et politique') THEN 'Système institutionnel et politique' WHEN p_theme='Droits et devoirs' THEN 'Droits et devoirs' WHEN p_theme IN ('Histoire','Histoire et symboles','France et Europe','Histoire, géographie et culture') THEN 'Histoire, géographie et culture' WHEN p_theme IN ('Vie en société','Société française','Vivre dans la société française') THEN 'Vivre dans la société française' ELSE p_theme END $$;
CREATE OR REPLACE FUNCTION public.validate_question_classification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.question_type NOT IN ('knowledge','scenario','unclassified') THEN RAISE EXCEPTION 'Type de question invalide.'; END IF; IF NEW.question_type<>'unclassified' AND (NEW.classification_source='' OR NEW.classification_reviewed_at IS NULL) THEN RAISE EXCEPTION 'Une source de classification et une relecture sont requises.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER question_classification_validation BEFORE INSERT OR UPDATE ON public.learning_questions FOR EACH ROW EXECUTE FUNCTION public.validate_question_classification();
CREATE OR REPLACE FUNCTION public.review_question_classification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE typ text:=coalesce(NEW.payload->>'question_type','unclassified'); proof text:=coalesce(NEW.payload->>'classification_source',''); BEGIN IF typ NOT IN ('knowledge','scenario','unclassified') THEN RAISE EXCEPTION 'Type de question invalide.'; END IF; IF typ<>'unclassified' AND proof='' THEN RAISE EXCEPTION 'Justification fiable de classification requise.'; END IF; IF NEW.status='verified' AND typ<>'unclassified' AND NOT public.admin_can('publish') THEN RAISE EXCEPTION 'Relecture non autorisée.'; END IF; IF NEW.status='published' THEN UPDATE public.learning_questions SET question_type=typ,classification_source=proof,classification_reviewed_at=CASE WHEN typ<>'unclassified' THEN now() ELSE NULL END WHERE id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER draft_classification_review AFTER INSERT OR UPDATE ON public.question_drafts FOR EACH ROW EXECUTE FUNCTION public.review_question_classification();
CREATE OR REPLACE FUNCTION public.start_classified_practice(p_count integer DEFAULT 10,p_type text DEFAULT 'all',p_theme text DEFAULT NULL,p_correction text DEFAULT 'immediate',p_chrono boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE path text; qs jsonb; sid uuid; available integer; rules jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Connectez-vous pour commencer.'; END IF; IF p_count IS NULL OR p_count NOT IN (5,10,20) THEN RAISE EXCEPTION 'Choisissez exactement 5, 10 ou 20 questions.'; END IF; IF p_type IS NULL OR p_type NOT IN ('all','knowledge','scenario','unclassified') THEN RAISE EXCEPTION 'Type de question invalide.'; END IF; IF p_correction NOT IN ('immediate','fin') THEN RAISE EXCEPTION 'Correction invalide.'; END IF; SELECT parcours INTO path FROM public.profiles WHERE id=auth.uid(); IF path IS NULL THEN RAISE EXCEPTION 'Profil indisponible.'; END IF; rules:=jsonb_build_object('question_type',p_type,'theme',p_theme,'correction',p_correction,'chrono',p_chrono,'allow_aids',true); PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text||path||'practice')); SELECT id INTO sid FROM public.learning_sessions WHERE user_id=auth.uid() AND parcours=path AND kind='practice' AND completed_at IS NULL AND test_id IS NULL AND total=p_count AND test_rules=rules ORDER BY started_at DESC LIMIT 1; IF sid IS NOT NULL THEN RETURN sid; END IF;
SELECT count(*) INTO available FROM public.learning_questions WHERE published AND path=ANY(pathways) AND (p_theme IS NULL OR public.civic_topic(coalesce(exam_theme,theme))=public.civic_topic(p_theme)) AND (p_type='all' OR question_type=p_type) AND (p_type NOT IN ('knowledge','scenario') OR classification_reviewed_at IS NOT NULL);
IF available<p_count THEN RAISE EXCEPTION 'Questions disponibles : %. Choisissez un autre thème, un autre type ou 5 questions si disponibles.',available; END IF;
SELECT jsonb_agg(to_jsonb(q) ORDER BY q.position) INTO qs FROM (SELECT * FROM public.learning_questions WHERE published AND path=ANY(pathways) AND (p_theme IS NULL OR public.civic_topic(coalesce(exam_theme,theme))=public.civic_topic(p_theme)) AND (p_type='all' OR question_type=p_type) AND (p_type NOT IN ('knowledge','scenario') OR classification_reviewed_at IS NOT NULL) ORDER BY position LIMIT p_count) q;
INSERT INTO public.learning_sessions(user_id,parcours,kind,questions,total,test_rules) VALUES(auth.uid(),path,'practice',qs,p_count,rules) RETURNING id INTO sid; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.start_classified_practice(integer,text,text,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.start_classified_practice(integer,text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_session_configuration() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.kind='exam' AND NEW.total=40 AND EXISTS(SELECT 1 FROM unnest(ARRAY['Principes et valeurs de la République française','Système institutionnel et politique','Droits et devoirs','Histoire, géographie et culture','Vivre dans la société française']) t WHERE (SELECT count(*) FROM public.learning_questions q WHERE q.published AND NEW.parcours=ANY(q.pathways) AND public.civic_topic(coalesce(q.exam_theme,q.theme))=t)<8) THEN RAISE EXCEPTION 'Simulation complète indisponible : au moins un des cinq thèmes ne possède pas 8 questions publiées pour votre parcours. Les exercices thématiques restent disponibles.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER session_coverage_guard BEFORE INSERT ON public.learning_sessions FOR EACH ROW EXECUTE FUNCTION public.guard_session_configuration();
CREATE OR REPLACE FUNCTION public.validate_configured_question_type() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE typ text; BEGIN IF TG_TABLE_NAME='learning_tests' THEN typ:=NEW.question_type; IF typ NOT IN ('all','knowledge','scenario','unclassified') THEN RAISE EXCEPTION 'Type de question invalide.'; END IF; IF NEW.status='published' AND typ<>'all' AND EXISTS(SELECT 1 FROM unnest(NEW.pathways) path WHERE (SELECT count(*) FROM public.learning_questions q WHERE q.published AND path=ANY(q.pathways) AND q.question_type=typ AND (typ='unclassified' OR q.classification_reviewed_at IS NOT NULL) AND (cardinality(NEW.themes)=0 OR q.theme=ANY(NEW.themes) OR q.exam_theme=ANY(NEW.themes)) AND (NEW.selection<>'fixed' OR q.id=ANY(NEW.question_ids)))<NEW.question_count) THEN RAISE EXCEPTION 'Questions du type choisi insuffisantes pour un parcours.'; END IF; ELSE SELECT question_type INTO typ FROM public.learning_tests WHERE id=NEW.test_id; IF typ IS NOT NULL AND typ<>'all' AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.questions) q WHERE q->>'question_type' IS DISTINCT FROM typ) THEN RAISE EXCEPTION 'La sélection ne respecte pas le type configuré.'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER configured_type_validation BEFORE INSERT OR UPDATE ON public.learning_tests FOR EACH ROW EXECUTE FUNCTION public.validate_configured_question_type();
CREATE TRIGGER configured_session_type_validation BEFORE INSERT ON public.learning_sessions FOR EACH ROW EXECUTE FUNCTION public.validate_configured_question_type();